import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.vLhlLNVn.js";const s="/assets/einrichten.DLQPpRAI.png",q=JSON.parse('{"title":"Installation and requirements","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/01.erste-schritte/01.installation.md"},"headers":[],"relativePath":"adapter/sourceanalytix/erste-schritte/installation.md","filePath":"adapter/sourceanalytix/erste-schritte/installation.md","lastUpdated":null}'),i={name:"adapter/sourceanalytix/erste-schritte/installation.md"};function r(l,e,d,c,u,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="installation-and-requirements" tabindex="-1">Installation and requirements <a class="header-anchor" href="#installation-and-requirements" aria-label="Permalink to &quot;Installation and requirements&quot;">​</a></h1><p><a id="requirements-sourceanalytix-have-node-js"></a></p><h2 id="what-does-sourceanalytix-require-node-js-js-controller-admin" tabindex="-1">What does SourceAnalytix require (Node.js, js-controller, Admin)? <a class="header-anchor" href="#what-does-sourceanalytix-require-node-js-js-controller-admin" aria-label="Permalink to &quot;What does SourceAnalytix require (Node.js, js-controller, Admin)?&quot;">​</a></h2><p>You need Node.js 22, js-controller 6.0.11 and Admin 8.0.0 or newer. Admin 8 is required because the instance settings page is built from Admin 8 components.</p><p>The console shows your versions with <code>iobroker -v</code> (js-controller) and <code>node -v</code> (Node.js). If a component is too old, update it first and SourceAnalytix afterwards.</p><h3 id="sourceanalytix-does-not-start-after-a-node-js-update" tabindex="-1">SourceAnalytix does not start after a Node.js update <a class="header-anchor" href="#sourceanalytix-does-not-start-after-a-node-js-update" aria-label="Permalink to &quot;SourceAnalytix does not start after a Node.js update&quot;">​</a></h3><p>If the log shows <code>TypeError: Class extends value … is not a constructor or null</code>, js-controller is usually too old. Update it, run <code>iob fix</code> and restart the instance. In Docker, update the container image instead.</p><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix?</a> · <a href="./../fehlerbehebung/log-meldungen#installation-admin-display-problems">Problems with installation and the Admin display</a></p><p><a id="install-sourceanalytix-create-instance"></a></p><h2 id="how-do-i-install-sourceanalytix-and-create-an-instance" tabindex="-1">How do I install SourceAnalytix and create an instance? <a class="header-anchor" href="#how-do-i-install-sourceanalytix-and-create-an-instance" aria-label="Permalink to &quot;How do I install SourceAnalytix and create an instance?&quot;">​</a></h2><p>SourceAnalytix is in the &quot;latest&quot; repository (beta), not yet in &quot;stable&quot;. Switch to &quot;latest&quot;, install the adapter and then set up your first source in the instance settings.</p><ol><li>In Admin, choose the &quot;latest&quot; repository under System settings › &quot;Repositories&quot;.</li><li>Search for &quot;SourceAnalytix&quot; on the &quot;Adapters&quot; tab and install it. Admin creates the instance <code>sourceanalytix.0</code> and starts it.</li><li>Open the settings of <code>sourceanalytix.0</code> on the &quot;Instances&quot; tab.</li><li>Create at least one price on the &quot;Price definitions&quot; tab, for example for electricity in kWh, and save.</li><li>Click &quot;Add first source&quot; on the &quot;Overview&quot; tab. Continue with <a href="./erster-zaehler#configure-sourceanalytix-datapoint">My first meter</a>.</li></ol><p><img src="'+s+'" alt="The &quot;Overview&quot; tab right after installation, with the &quot;Set up SourceAnalytix&quot; card"></p><p>The &quot;Overview&quot; and &quot;Problems&quot; tabs need a running instance. If it is stopped, &quot;Instance is not running&quot; appears at the top with a &quot;Start&quot; button.</p><h3 id="there-is-no-instance" tabindex="-1">There is no instance <a class="header-anchor" href="#there-is-no-instance" aria-label="Permalink to &quot;There is no instance&quot;">​</a></h3><p>After installing from the console or a GitHub URL, the instance is missing. Create it on the &quot;Adapters&quot; tab with the plus icon. A GitHub installation is only meant for testing, and Admin shows no updates for it.</p><p><strong>See also:</strong> <a href="#need-several-instances-versions-side">Do I need several instances?</a></p><p><a id="need-several-instances-versions-side"></a></p><h2 id="do-i-need-several-instances-or-versions-side-by-side" tabindex="-1">Do I need several instances or versions side by side? <a class="header-anchor" href="#do-i-need-several-instances-or-versions-side-by-side" aria-label="Permalink to &quot;Do I need several instances or versions side by side?&quot;">​</a></h2><p>No. One instance handles any number of sources. Two versions side by side are not possible, because ioBroker installs exactly one version of each adapter. To test a new version, make a backup and update.</p><h3 id="removing-a-surplus-instance" tabindex="-1">Removing a surplus instance <a class="header-anchor" href="#removing-a-surplus-instance" aria-label="Permalink to &quot;Removing a surplus instance&quot;">​</a></h3><ol><li>On the &quot;Objects&quot; tab, check which instance holds your values, <code>sourceanalytix.0</code> or <code>sourceanalytix.1</code>.</li><li>Delete the other instance on the &quot;Instances&quot; tab with the bin icon.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Deleting an instance also deletes all its values. To only take a source out of service, use &quot;Deactivate&quot; on that source.</p></div><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#disable-datapoint-remove-sources-states">Disable a datapoint or remove a source</a></p>',24)])])}const m=t(i,[["render",r]]);export{q as __pageData,m as default};
